        public:
            Panel_AMOLED(void) { }

            ~Panel_AMOLED(void)
            {
              deinitPanelFb();
            }

            bool init(bool use_reset) override;
            void beginTransaction(void) override;
            void endTransaction(void) override;


            bool initPanelFb()
            {
              if(_panel_fb)
                return true;
              auto fb = new (std::nothrow) Panel_AMOLED_Framebuffer(this);
              if (!fb)
                return false;
              fb->config(_cfg);
              fb->setColorDepth(_write_depth);
              fb->setRotation(getRotation());
              // Keep _panel_fb null on failure: a leftover object without a
              // buffer would make the next call report success and route
              // display() through a framebuffer that does not exist.
              if (!fb->init(false))
              {
                delete fb;
                return false;
              }
              _panel_fb = fb;
              return true;
            }

            void deinitPanelFb()
            {
              if(_panel_fb) {
                delete _panel_fb;
                _panel_fb = nullptr;
              }
            }

            Panel_AMOLED_Framebuffer* getPanelFb()
            {
